pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        vm.assume(target != address(0));
        vm.assume(value <= 1 ether);

        address owner = c.Owner();
        uint256 balanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = address(owner).balance;

        // Prepare data for Command call
        bytes memory data = "";

        // Call Command with value
        (bool success, ) = address(c).call{value: value}(abi.encodeWithSelector(c.Command.selector, target, data));

        if (success) {
            uint256 balanceAfter = address(c).balance;
            uint256 ownerBalanceAfter = address(owner).balance;
            uint256 netOwnerChange = ownerBalanceAfter - ownerBalanceBefore;
            // General rule: contract balance after <= owner's initial balance + sent value - owner's increase
            assertTrue(balanceAfter <= balanceBefore + value - netOwnerChange);
        } else {
            // If revert, we consider the invariant trivially holds
            assertTrue(true);
        }
    }
}

