pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, uint256 amount) public {
        vm.assume(adr != address(0) && adr != address(c) && adr != address(this));
        uint256 balBefore = address(c).balance;
        vm.deal(address(c), balBefore);
        // Execute Command as Owner (msg.sender)
        vm.prank(c.Owner());
        bytes memory data = "";
        bool commandSuccess;
        // We need to also handle potential revert; we will call with value
        commandSuccess = address(c).call{value: amount}(abi.encodeWithSignature("Command(address,bytes)", adr, data));
        // Then call withdraw
        (bool withdrawSuccess, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        // The rule: withdraw succeeds OR contract balance is zero
        assertTrue(withdrawSuccess || address(c).balance == 0);
    }
}

