pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, bytes memory data) public {
        vm.assume(adr != address(0) && adr != address(c) && adr != address(this));
        uint256 initialBalance = address(c).balance;
        uint256 msgValue = 1e18;
        vm.deal(address(this), msgValue);

        // Fund the contract so the call can succeed
        vm.deal(address(c), 1e18);

        // Record the contract's balance before the call
        uint256 balanceBefore = address(c).balance;

        // Execute Command with msg.value > 0
        (bool success, ) = address(c).call{value: msgValue}(abi.encodeWithSignature("Command(address,bytes)", adr, data));

        // The rule: if the call succeeded, the contract's balance should have decreased by msg.value (since it forwarded it)
        // If the call reverted, the balance should remain the same
        if (success) {
            assertTrue(address(c).balance <= balanceBefore - msgValue, "Balance should decrease by msg.value on success");
        } else {
            assertTrue(address(c).balance >= balanceBefore - msgValue, "Balance should not decrease by msg.value on revert");
        }
    }
}

