pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address recipient, uint256 initialBalance, uint256 commandValue) public {
        vm.assume(caller != address(0) && recipient != address(0));
        vm.assume(initialBalance <= 1e18);
        vm.assume(commandValue <= 1e18);
        vm.assume(initialBalance == commandValue);

        // Fund the contract
        vm.deal(address(c), initialBalance);

        // Set owner
        vm.prank(address(c.Owner()));

        uint256 balanceBefore = address(c).balance;
        bytes memory data = "";
        c.Command{value: commandValue}(recipient, data);
        uint256 balanceAfter = address(c).balance;

        // In the reference, multiplicate triggers when msg.value >= balance (including equality), transferring balance + msg.value = 2*initialBalance out.
        // In the mutant, equality does not trigger, so no transfer occurs and balance becomes initialBalance + commandValue = 2*initialBalance.
        // So the rule: balanceAfter should be 0 (reference) OR 2*initialBalance (mutant). We assert it is 0 in reference.
        assertTrue(balanceAfter == 0 || balanceAfter == 2 * initialBalance);
    }
}

