contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, uint256 initialBalance, uint256 msgValue) public {
        // Bound initialBalance and msgValue to reasonable values
        initialBalance = bound(initialBalance, 1, 1e18);
        msgValue = bound(msgValue, 1, 1e18);
        // Ensure the condition msg.value >= address(this).balance is exactly true in reference
        // i.e., msgValue must be exactly equal to initialBalance (the edge case)
        vm.assume(msgValue == initialBalance);

        // Start from a fresh contract
        c = new C();
        vm.deal(address(c), initialBalance);
        vm.deal(address(this), 1 ether);

        // Record balance before Command
        uint256 balanceBefore = address(c).balance;

        // Call Command as owner to trigger multiplicate
        vm.prank(address(this)); // Owner is msg.sender of constructor
        bytes memory emptyData;
        c.Command{value: msgValue}(adr, emptyData);

        uint256 balanceAfter = address(c).balance;

        // General rule: The balance should have been reduced by msgValue if the condition triggered
        // In reference: if(msg.value >= balance) triggers, so balanceAfter = balanceBefore - msgValue
        // In mutant: if(msg.value > balance) does NOT trigger, so balanceAfter = balanceBefore
        // Since msgValue == balanceBefore, reference reduces balance to 0, mutant leaves balance unchanged.
        // So we assert that balanceAfter is either 0 or balanceBefore (both are >= balanceBefore - msgValue)
        // But to avoid false negatives, we assert that the reduction is exactly msgValue or 0.
        // Since we know the exact behavior, we can assert that balanceAfter == 0 in reference, but in mutant it's >= balanceBefore.
        // To have a single rule that reference passes and mutant fails, we assert balanceAfter <= balanceBefore - msgValue + 1
        // Actually, simpler: reference always gives balanceAfter = balanceBefore - msgValue (0), mutant gives balanceAfter = balanceBefore (positive).
        // So we can assert balanceAfter < balanceBefore (strictly less). Reference passes; mutant fails because balanceAfter == balanceBefore.
        assertTrue(balanceAfter < balanceBefore, "Balance should decrease after Command with msg.value == contract balance");
    }
}

